rd[3304664][7]["RewardStrengthValue"] = {}	tChineseValentinesDayPack_Reward[3304664][7]["RewardStrengthValue"]["Value"] = 400	tChineseValentinesDayPack_Reward[3304664][7]["LogId"] = 12000826	tChineseValentinesDayPack_Reward[3304664][7]["RewardEffect"] = {}	tChineseValentinesDayPack_Reward[3304664][7]["RewardEffect"]["Effect"] = tChineseValentinesDayPack_Data["Effect"]	tChineseValentinesDayPack_Reward[3304664][7]["RewardBroadCast"] = tChineseValentinesDayPack_Text["RewardBroadCast"]		tChineseValentinesDayPack_Reward[3304664][8] = {}	tChineseValentinesDayPack_Reward[3304664][8]["RewardItem"] = {}	tChineseValentinesDayPack_Reward[3304664][8]["RewardItem"][1] = {}	tChineseValentinesDayPack_Reward[3304664][8]["RewardItem"][1]["Id"] = 3009001	tChineseValentinesDayPack_Reward[3304664][8]["RewardItem"][1]["Attr"] = "0 2 0 2880 1"	tChineseValentinesDayPack_Reward[3304664][8]["RewardStrengthValue"] = {}	tChineseValentinesDayPack_Reward[3304664][8]["RewardStrengthValue"]["Value"] = 500	tChineseValentinesDayPack_Reward[3304664][8]["RewardEMoneyMono"] = {}	tChineseValentinesDayPack_Reward[3304664][8]["RewardEMoneyMono"]["Value"] = 77	tChineseValentinesDayPack_Reward[3304664][8]["LogId"] = 12000826	tChineseValentinesDayPack_Reward[3304664][8]["RewardEffect"] = {}	tChineseValentinesDayPack_Reward[3304664][8]["RewardEffect"]["Effect"] = tChineseValentinesDayPack_Data["Effect"]	tChineseValentinesDayPack_Reward[3304664][8]["RewardBroadCast"] = tChineseValentinesDayPack_Text["RewardBroadCast"]		-- 3304822 浪漫七夕大礼包	tChineseValentinesDayPack_Reward[3304822] = {}	tChineseValentinesDayPack_Reward[3304822]["RewardItem"] = {}	tChineseValentinesDayPack_Reward[3304822]["RewardItem"][1] = {}	tChineseValentinesDayPack_Reward[3304822]["RewardItem"][1]["Id"] = 194875	tChineseValentinesDayPack_Reward[3304822]["RewardItem"][1]["Attr"] = "0 1 0 0 0 0 0 1"	tChineseValentinesDayPack_Reward[3304822]["DeleteItem"] = {}	tChineseValentinesDayPack_Reward[3304822]["DeleteItem"][1] = {}	tChineseValentinesDayPack_Reward[3304822]["DeleteItem"][1]["Id"] = 3304822	tChineseValentinesDayPack_Reward[3304822]["LogId"] = 12000826	tChineseValentinesDayPack_Reward[3304822]["EmoneyLog"] = "250	4882	11040	11040	1	"	tChineseValentinesDayPack_Reward[3304822]["RewardEffect"] = {}	tChineseValentinesDayPack_Reward[3304822]["RewardEffect"]["Effect"] = tChineseValentinesDayPack_Data["Effect"]--------------------------------------逻辑部分--------------------------------------------- 上线触发function ChineseValentinesDayPack_GetPack()	-- 判断时间	if not Sys_ChkFullTime(tActivityTime["ChineseValentinesDay"]["ActivityTime"]) then		return	end		-- 判断等级	if not User_JudgeLevelAndMetempsychosis(tChineseValentinesDayPack_Data["Level"],tChineseValentinesDayPack_Data["Metempsychosis"]) then		return	end		-- 判断物品	local nItemId = tChineseValentinesDayPack_Data["Itemtype"]["Pack"]	if Item_ChkItem(nItemId) then		return	end		-- 判断掩码	local nEventType = tChineseValentinesDayPack_Data["Stc"]["Login"]["EventType"]	local nDataType = tChineseValentinesDayPack_Data["Stc"]["Login"]["DataType"]	local nComplete = tChineseValentinesDayPack_Data["Stc"]["Login"]["Complete"]	if Task_ChkStcValue(nEventType,nDataType,">=",nComplete) then		return	end		-- 判断背包	local nSpace = RewardTemplate_GetRewardSpace(tChineseValentinesDayPack_Reward["Login"])	if not User_CheckLeftSpace(nSpace) then		User_TalkChannel2005(tChineseValentinesDayPack_Text["LoginSpace"])		return	end		----------------------------------------- 获得物品		Task_SetStatistic(nEventType,nDataType,nComplete,1)	RewardTemplate_UseItemAndMsg(tChineseValentinesDayPack_Reward["Login"])end-- 3304664 浪漫七夕大礼包function ChineseValentinesDayPack_OpenPack(nItemId)	-- 判断物品	if not Item_ChkItem(nItemId) then		return	end		-- 判断时间	-- 后	if CommonFunc_GetAfterActivityTime(tActivityTime["ChineseValentinesDay"]["ActivityTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tChineseValentinesDayPack_Text["Overdue"])		Sys_SaveActionFestivalLog(tChineseValentinesDayPack_Data["Log"]["OverdueDelete"])		return	end		-- 判断掩码	-- stc(164,72) 记录礼包每天打开的情况	local nEventType = tChineseValentinesDayPack_Data["Stc"]["Open"]["EventType"]	local nDataType = tChineseValentinesDayPack_Data["Stc"]["Open"]["DataType"]	local nComplete = tChineseValentinesDayPack_Data["Stc"]["Open"]["Complete"]	Task_StcReset(nEventType,nDataType)	if Task_ChkStcValue(nEventType,nDataType,">=",nComplete) then		User_TalkChannel2005(tChineseValentinesDayPack_Text["AlreadyOpened"])		return	end		-- 判断背包	-- stc(163,83) 记录玩家开启每颗星星的奖励礼包的情况	local nLevelEventType = tChineseValentinesDayPack_Data["Stc"]["Level"]["EventType"]	local nLevelDataType = tChineseValentinesDayPack_Data["Stc"]["Level"]["DataType"]	local nValue = Get_UserStatisticValue(nLevelEventType,nLevelDataType)	local nSpace = RewardTemplate_GetRewardSpace(tChineseValentinesDayPack_Reward[nItemId][nValue+1])	local sMsg = string.format(tChineseValentinesDayPack_Text["NoSpace"],nSpace)	if not User_CheckLeftSpace(nSpace) then		User_TalkChannel2005(sMsg)		return	end		-- 判断赠点	if nValue == tChineseValentinesDayPack_Data["EmoneyMono"]["Level"] then		local nMaxRewardMonoEMoney = tChineseValentinesDayPack_Reward[nItemId][8]["RewardEMoneyMono"]["Value"]		if Get_UserMonoEMoney() + nMaxRewardMonoEMoney > G_User_MaxEmoneyMono then			User_TalkChannel2005(tChineseValentinesDayPack_Text["TooMuch"] )			return		end	end		----------------------------------------- 给奖		Task_SetStatistic(nEventType,nDataType,nComplete,1)	Task_SetStcTimestamp(nEventType,nDataType,0)	RewardTemplate_UseItemAndMsg(tChineseValentinesDayPack_Reward[nItemId][nValue+1])end-- 3304822 紫音青衫【霞光】优惠包function ChineseValentinesDayPack_OpenCoatPack(nItemId)	-- 判断天石	local nNeedEMoney = tChineseValentinesDayPack_Data["EmoneyMono"]["Need"]	if Get_UserEMoney() < nNeedEMoney then		LinkItemGossipFunc_New(nItemId,"3-1")		return	end		if User_AddEMoney(-nNeedEMoney) then		RewardTemplate_UseItemAndMsg(tChineseValentinesDayPack_Reward[nItemId])	endend--------------------------------------物品配置--------------------------------------------- 3304664 浪漫七夕大礼包tItemFace[3304664] = 796tItem[3304664] = tItem[3304664] or {}tItem[3304664]["DialogueText"] = tChineseValentinesDayPack_Text[3304664]tItem[3304664]["Function"] = function(nItemId,sItemName)	-- 判断物品	if not Item_ChkItem(nItemId) then		return	end		-- 判断时间	-- 后	if CommonFunc_GetAfterActivityTime(tActivityTime["ChineseValentinesDay"]["ActivityTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tChineseValentinesDayPack_Text["Overdue"])		Sys_SaveActionFestivalLog(tChineseValentinesDayPack_Data["Log"]["OverdueDelete"])		return	end		LinkItemGossipFunc_New(nItemId,"1-1")endtItem[3304664]["Text1-1"] = {111,112,113,114,112,115,116}tItem[3304664]["tOption1-1"] = {1,2}tItem[3304664]["ChkFunc1-1"] = function()	-- stc(164,72) 记录礼包每天打开的情况	local nEventType = tChineseValentinesDayPack_Data["Stc"]["Open"]["EventType"]	local nDataType = tChineseValentinesDayPack_Data["Stc"]["Open"]["DataType"]	local nComplete = tChineseValentinesDayPack_Data["Stc"]["Open"]["Complete"]	Task_StcReset(nEventType,nDataType)	if Task_ChkStcValue(nEventType,nDataType,">=",nComplete) then		tItem[3304664]["Option1"] = tChineseValentinesDayPack_Text[3304664]["Option1"] .. tChineseValentinesDayPack_Text["Opened"]	else		tItem[3304664]["Option1"] = tChineseValentinesDayPack_Text[3304664]["Option1"]	end		-- stc(163,83) 记录玩家开启每颗星星的奖励礼包的情况	local nLevelEventType = tChineseValentinesDayPack_Data["Stc"]["Level"]["EventType"]	local nLevelDataType = tChineseValentinesDayPack_Data["Stc"]["Level"]["DataType"]	local nValue = Get_UserStatisticValue(nLevelEventType,nLevelDataType)	tItem[3304664]["Text113"] = string.format(tChineseValentinesDayPack_Text[3304664]["Text113"],nValue)		local sReward = tChineseValentinesDayPack_Text[nValue+1]	tItem[3304664]["Text114"] = string.format(tChineseValentinesDayPack_Text[3304664]["Text114"],sReward)		return trueendtItem[3304664]["OptionFunc1"] = "ChineseValentinesDayPack_OpenPack</N>3304664"tItem[3304664]["OptionPoint2"] = "2-1"tItem[3304664]["Text2-1"] = {211,212,213,214,215,216,217,218,219,220,221,212,222}tItem[3304664]["tOption2-1"] = {3}tItem[3304664]["OptionPoint3"] = "1-1"-- 3304822 紫音青衫【霞光】优惠包tItemFace[3304822] = 798tItem[3304822] = tItem[3304822] or {}tItem[3304822]["DialogueText"] = tChineseValentinesDayPack_Text[3304822]tItem[3304822]["Text1-1"] = {111,112}tItem[3304822]["tOption1-1"] = {111,112}tItem[3304822]["OptionPoint111"] = "2-1"tItem[3304822]["Text2-1"] = {211}tItem[3304822]["tOption2-1"] = {211,212}tItem[3304822]["OptionFunc211"] = "ChineseValentinesDayPack_OpenCoatPack</N>3304822"tItem[3304822]["Text3-1"] = {311}tItem[3304822]["tOption3-1"] = {311}--------------------------------------上线触发---------------------------------------------table.insert(tSystem_PlayLogin_Func,ChineseValentinesDayPack_GetPack)